import{_ as e,c as l,o as i,ag as s}from"./chunks/framework.C86mscM5.js";const u=JSON.parse('{"title":"SLI、SLO 与错误预算","description":"","frontmatter":{},"headers":[],"relativePath":"devops/security-reliability/sli-slo.md","filePath":"devops/security-reliability/sli-slo.md","lastUpdated":1788689791000}'),t={name:"devops/security-reliability/sli-slo.md"};function o(r,a,n,p,d,c){return i(),l("div",null,a[0]||(a[0]=[s(`<h1 id="sli、slo-与错误预算" tabindex="-1">SLI、SLO 与错误预算 <a class="header-anchor" href="#sli、slo-与错误预算" aria-label="Permalink to &quot;SLI、SLO 与错误预算&quot;">​</a></h1><ul><li><strong>SLI</strong>：对服务行为的量化指标，例如成功请求比例或 P95 延迟。</li><li><strong>SLO</strong>：在时间窗口内期望达到的 SLI 目标。</li><li><strong>SLA</strong>：与客户约定的承诺及未达到时的后果，通常比内部 SLO 更宽松。</li></ul><h2 id="选择-sli" tabindex="-1">选择 SLI <a class="header-anchor" href="#选择-sli" aria-label="Permalink to &quot;选择 SLI&quot;">​</a></h2><p>优先从用户可感知结果定义：</p><ul><li>前端：页面加载成功率、关键交互成功率、LCP/INP 分位数。</li><li>API：有效请求成功率、P95/P99 延迟、响应正确性。</li><li>异步任务：在规定时间内处理成功的任务比例。</li><li>数据系统：新鲜度、完整性和查询成功率。</li></ul><p>不要把 CPU 使用率直接当作服务 SLI，它更适合作为诊断和容量指标。</p><h2 id="计算示例" tabindex="-1">计算示例 <a class="header-anchor" href="#计算示例" aria-label="Permalink to &quot;计算示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>成功率 SLI = 符合条件的成功请求数 / 符合条件的全部请求数</span></span>
<span class="line"><span>错误预算 = 1 - SLO</span></span></code></pre></div><p>月度可用性目标 99.9% 对应约 0.1% 的失败预算。统计前需定义窗口、有效请求、客户端取消、健康检查和计划维护是否计入。</p><h2 id="错误预算" tabindex="-1">错误预算 <a class="header-anchor" href="#错误预算" aria-label="Permalink to &quot;错误预算&quot;">​</a></h2><p>错误预算未消耗时可以保持正常发布节奏；快速消耗时暂停高风险发布，优先修复可靠性、测试和观测缺口。它是产品与工程共同做取舍的机制，不是惩罚团队的指标。</p><h2 id="告警" tabindex="-1">告警 <a class="header-anchor" href="#告警" aria-label="Permalink to &quot;告警&quot;">​</a></h2><p>基于多窗口、多消耗速率告警：短窗口发现快速事故，长窗口发现持续退化。告警应包含受影响 SLO、当前消耗速率、版本变更、Dashboard 和 Runbook。</p>`,13)]))}const S=e(t,[["render",o]]);export{u as __pageData,S as default};
